/**
 * Jinx Alchemist + Boffin: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Alchemist
 * Wiki: https://wiki.bloodontheclocktower.com/Boffin
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { notShownGiven } from '#lib/core/rules/jinx-effects.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { alchemistAs, scriptOf } from './alchemist.test-support.ts';

describe('Alchemist + Boffin jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'alchemist', 'boffin');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('alchemist')?.name).toBe('Alchemist');
		expect(data.byId.get('boffin')?.name).toBe('Boffin');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['alchemist', 'boffin'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['alchemist'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['boffin'])).not.toContain(jinx);
	});

	describe('an Alchemist-Boffin does not learn the Demon’s ability', () => {
		const base = alchemistAs('boffin', ['chef', 'empath', 'imp', 'monk']);
		const alerts = (s: typeof base) =>
			nightStepAlerts(s.game, 'boffin', s.characters).filter((a) => a.kind === 'not-shown-given');

		it("is data in the Alchemist's rules", () => {
			// Wiki: "If the Alchemist has the Boffin ability, the Alchemist does not learn what ability the Demon has."
			expect(jinxRulesBetween('alchemist', 'boffin', committedCharacters())).toEqual({
				notShown: { what: 'given-ability' }
			});
		});

		it('says at the Boffin step that the Alchemist is not shown the ability', () => {
			// Wiki: "the Alchemist does not learn what ability the Demon has."
			expect(notShownGiven(base.game, base.characters)).toEqual([
				{ seatId: base.seat(0), owner: 'alchemist', partner: 'boffin' }
			]);
			expect(alerts(base)).toMatchObject([
				{ kind: 'not-shown-given', seatId: base.seat(0), partner: 'boffin' }
			]);
		});

		it('says nothing for the real Boffin', () => {
			// Wiki: "If the Alchemist has the Boffin ability"
			const ids = ['alchemist', 'boffin', 'chef', 'empath', 'imp'];
			const s = scenario(['boffin', 'chef', 'empath', 'imp'], { script: scriptOf(ids) });
			expect(notShownGiven(s.game, s.characters)).toEqual([]);
			expect(alerts(s)).toEqual([]);
		});
	});
});
